(720, 1, '2026-03-19 06:26:37', '2026-03-19 06:26:37', '@keyframes shadow-pulse\n{\n  0% {\n    box-shadow: 0 0 0 0px rgba(255, 255, 255, 0.4);\n  }\n  100% {\n    box-shadow: 0 0 0 20px rgba(255, 255, 255, 0);\n  }\n}\n.pulso-animation:before {\n    content: \"\";\n    letter-spacing: 1px;\n    color: #fff;\n    text-align: center;\n    border-radius: 50%;\n    animation: shadow-pulse 2s infinite;\n    width: 15px;\n    height: 15px;\n    border: 3px solid #fff;\n    position: absolute;\n    left: 22px;\n    top: 3px;\n    bottom: 0;\n    margin: auto;\n}\n.contact-form label {\n    color: #000;\n    font-weight: 500;\n}\n.contact-form .col-6 {\n    width: 50%;\n    float: left;\n}\n.contact-form .pr{\n	padding-right:10px;\n}\n.contact-form .pl{\n	padding-left:10px;\n}\n.contact-form input, .contact-form textarea {\n    margin-bottom: 20px !important;\n    background: rgba(0,0,0,.04) !important;\n    border: 1px solid  rgba(0,0,0,.04) !important;\n    border-radius: 5px !important;\n    color: #333333 !important;\n    font-size: 17px !important;\n    font-weight: 500 !important;\n}\n.contact-form textarea{\n	height:100px !important\n}\n\n', 'bridge', '', 'publish', 'closed', 'closed', '', 'bridge', '', '', '2026-03-19 13:09:48', '2026-03-19 13:09:48', '', 0, 'http://exogatech.acutetest.com/2026/03/19/bridge/', 0, 'custom_css', '', 0),
