(933, 1, '2026-03-19 12:29:57', '2026-03-19 12:29:57', '@keyframes shadow-pulse\n{\n  0% {\n    box-shadow: 0 0 0 0px rgba(255, 255, 255, 0.4);\n  }\n  100% {\n    box-shadow: 0 0 0 20px rgba(255, 255, 255, 0);\n  }\n}\n.pulso-animation:before {\n    content: \"\";\n    letter-spacing: 1px;\n    color: #fff;\n    text-align: center;\n    border-radius: 50%;\n    animation: shadow-pulse 2s infinite;\n    width: 15px;\n    height: 15px;\n    border: 3px solid #fff;\n    position: absolute;\n    left: 22px;\n    top: 3px;\n    bottom: 0;\n    margin: auto;\n}\n.contact-form label {\n    color: #fff;\n    font-weight: 500;\n}\n.contact-form .col-6 {\n    width: 50%;\n    float: left;\n}\n.contact-form .pr{\n	padding-right:10px;\n}\n.contact-form .pl{\n	padding-left:10px;\n}\n.contact-form input, .contact-form textarea {\n    margin-bottom: 20px !important;\n    background: transparent !important;\n    border: 1px solid #fff !important;\n    border-radius: 5px !important;\n    color: #fff !important;\n    font-size: 17px !important;\n    font-weight: 500 !important;\n}\n.contact-form textarea{\n	height:100px !important\n}\n', 'bridge', '', 'inherit', 'closed', 'closed', '', '720-revision-v1', '', '', '2026-03-19 12:29:57', '2026-03-19 12:29:57', '', 720, 'http://exogatech.acutetest.com/?p=933', 0, 'revision', '', 0);
